def ekle(agac, x):
    if agac is None:
        return [x, None, None]
    if x < agac[0]:
        agac[1] = ekle(agac[1], x)
    else:
        agac[2] = ekle(agac[2], x)
    return agac

def sirala(agac):
    if agac is None:
        return []
    return sirala(agac[1]) + [agac[0]] + sirala(agac[2])

kok = None
for x in [5, 2, 8, 1]:
    kok = ekle(kok, x)
print(sirala(kok))
